from hypothesis import given, strategies as st
from textkit.pagination import paginate

@given(st.lists(st.integers()), st.integers(min_value=1, max_value=100))
def test_pagination_properties(items, page_size):
    pages = paginate(items, page_size)
    # Check that concatenated pages equal original items
    flattened = [item for page in pages for item in page]
    assert flattened == items
    # Check that all pages except possibly the last have length == page_size
    for page in pages[:-1]:
        assert len(page) == page_size
    # Check that last page has length <= page_size
    if pages:
        assert len(pages[-1]) <= page_size

try:
